import test from 'node:test';import assert from 'node:assert/strict';import {Pacman,MAZE,COLS,ROWS} from '../rules.js';
const step=(g,n=120)=>{for(let i=0;i<n;i++)g.update(1/120)};
test('Every pellet is reachable without entering the ghost house',()=>{const g=new Pacman(),dist=g.distances(10,17);assert.equal(MAZE.length,ROWS);assert(MAZE.every(r=>r.length===COLS));for(const tile of g.pellets.keys())assert(dist.has(tile),tile+' is unreachable');assert(!g.can(10,9));assert(g.can(10,9,true))});
test('Dots, power pellets, frightened ghosts, fruit and bonus life score correctly',()=>{const g=new Pacman();g.player.cx=1;g.player.cy=1;g.collect();assert.equal(g.score,50);assert(g.fright>0);const ghost=g.ghosts[0];ghost.x=g.player.x=1;ghost.y=g.player.y=1;g.collision();assert.equal(g.score,250);assert.equal(ghost.mode,'return');g.points(10000);assert.equal(g.lives,4);g.points(10000);assert.equal(g.lives,4);g.fruit={x:1,y:1,life:5};g.collect();assert.equal(g.fruit,null)});
test('Movement buffers corners, reverses in a corridor and wraps the tunnel',()=>{const g=new Pacman();g.state='playing';g.ghosts=[];g.player=g.actor(0,11,2);g.requested=2;step(g,35);assert(g.player.cx>=19);const p=g.player;g.request(0);assert.equal(p.dir,0);step(g,10);assert(Number.isFinite(p.x));g.request(3);step(g,120);assert(g.can(g.player.cx,g.player.cy))});
test('Deaths remove one life; game over and pause cannot advance',()=>{const g=new Pacman();g.state='playing';const ghost=g.ghosts[0];ghost.x=g.player.x;ghost.y=g.player.y;g.collision();assert.equal(g.state,'dying');step(g,220);assert.equal(g.lives,2);g.pause();const before=JSON.stringify(g.player);step(g,100);assert.equal(JSON.stringify(g.player),before);g.pause();g.lives=1;g.state='dying';g.wait=.1;step(g,20);assert.equal(g.state,'over');assert.equal(g.lives,0)});
test('Last pellet advances level and all four ghosts navigate valid cells',()=>{const g=new Pacman();g.pellets.clear();g.pellets.set('10,17','.');g.collect();assert.equal(g.state,'clear');step(g,260);assert.equal(g.level,2);assert(g.pellets.size>0);g.state='playing';for(let i=0;i<2000;i++){g.update(1/120);if(g.state==='dying'){g.resetActors();g.state='playing'}for(const ghost of g.ghosts)assert(g.can(ghost.cx,ghost.cy,true),ghost.name+' entered a wall')}});
